4	// ci-performance-evaluation skill's first step names, and the only account of CI
5	// duration that is not somebody's impression. Per workflow, the MEDIAN duration
6	// over the last window against the median over the window before it. Median rather
7	// than mean because a single queued or retried run doubles a mean and says nothing
8	// about the suite.
9	//
10	// The verdict logic is pure and exported (`summarize`), so what counts as a
11	// regression is decided in one place and tested there rather than inferred from a
12	// live repo's weather.
13	
14	import { writeFileSync } from 'node:fs';
15	import { pathToFileURL } from 'node:url';
16	import { makeGh } from '../../../claudinite-tasks/shared-code/github.mjs';
17	import { findOrCreateTracker, writeTracker } from '../../../claudinite-tasks/shared-code/github.mjs';
18	
19	const item = process.env.CLAUDINITE_ITEM || '';
20	const log = (s) => console.log(`ci-performance${item ? ` [#${item}]` : ''}: ${s}`);
21	
22	export const WINDOW_DAYS = 7;
23	// A regression has to clear BOTH bars. The ratio alone fires on a fast workflow
24	// where a few seconds of runner weather is a large fraction; the absolute alone
25	// fires on a long workflow whose normal spread is wider than the threshold.
26	export const REGRESSION_RATIO = 1.25;
27	export const REGRESSION_SECONDS = 20;
28	// Below this, a median is one or two runs and describes the week's luck rather than
29	// the suite. Such a workflow is reported, never judged.
30	export const MIN_RUNS_PER_WINDOW = 3;
31	
32	export const median = (xs) => {
33	  if (!xs.length) return null;
34	  const s = [...xs].sort((a, b) => a - b);
35	  const m = s.length >> 1;
36	  return s.length % 2 ? s[m] : Math.round((s[m - 1] + s[m]) / 2);
37	};
38	
39	// Seconds a completed run took. `run_started_at` rather than `created_at`: the gap
40	// between them is queue time, which is the runner pool's business and moves for
41	// reasons no change to this repo can fix.
42	export function runSeconds(run) {
43	  const start = Date.parse(run.run_started_at || run.created_at);
44	  const end = Date.parse(run.updated_at);
45	  if (!Number.isFinite(start) || !Number.isFinite(end) || end < start) return null;
46	  return Math.round((end - start) / 1000);
47	}
48	
49	/**
50	 * Per-workflow medians for the current and previous window, and the regressions
51	 * among them. Pure — `runs` is the API's records, `nowMs` the reference instant.
52	 * A run outside both windows, still in progress, or unparseable is dropped.
53	 */
54	export function summarize(runs, nowMs, { windowDays = WINDOW_DAYS } = {}) {
55	  const windowMs = windowDays * 86400 * 1000;
56	  const byWorkflow = new Map();
57	  for (const run of runs) {
58	    if (run.status !== 'completed') continue;
59	    const seconds = runSeconds(run);
60	    if (seconds === null) continue;
61	    const age = nowMs - Date.parse(run.run_started_at || run.created_at);
62	    const bucket = age < 0 || age > 2 * windowMs ? null : age <= windowMs ? 'current' : 'previous';
63	    if (!bucket) continue;
64	    const name = run.name || run.path || 'unnamed';
65	    if (!byWorkflow.has(name)) byWorkflow.set(name, { name, current: [], previous: [] });
66	    byWorkflow.get(name)[bucket].push(seconds);
67	  }
68	
69	  const workflows = [...byWorkflow.values()].map((w) => {
70	    const current = median(w.current);
71	    const previous = median(w.previous);
72	    // "Comparable" is a property of the data, and it is reported: a workflow with
73	    // too few runs to judge must not read as a workflow that was judged and cleared.
74	    const comparable = w.current.length >= MIN_RUNS_PER_WINDOW && w.previous.length >= MIN_RUNS_PER_WINDOW;
75	    const regressed = comparable
76	      && current >= previous * REGRESSION_RATIO
77	      && current - previous >= REGRESSION_SECONDS;
78	    return { ...w, runs: w.current.length, priorRuns: w.previous.length, current, previous, comparable, regressed };
79	  }).sort((a, b) => (b.current ?? 0) - (a.current ?? 0));
80	
81	  return { workflows, regressions: workflows.filter((w) => w.regressed) };
82	}
83	
84	// The slowest step of one run, for the report — the skill's step 1 ("take the step
85	// breakdown before forming any theory"), pre-taken so the agent starts from the
86	// breakdown rather than spending its first calls fetching it.
87	export function slowestSteps(job, limit = 3) {
88	  return (job?.steps ?? [])
89	    .map((s) => {
90	      const start = Date.parse(s.started_at);
91	      const end = Date.parse(s.completed_at);
92	      return Number.isFinite(start) && Number.isFinite(end)
93	        ? { name: s.name, seconds: Math.round((end - start) / 1000) }
94	        : null;
95	    })
96	    .filter(Boolean)
97	    .sort((a, b) => b.seconds - a.seconds)
98	    .slice(0, limit);
99	}
100	
101	const fmt = (s) => (s === null ? '—' : `${s}s`);
102	
103	export function reportBody(summary, { repo, nowIso, steps = [] }) {
104	  const rows = summary.workflows.map((w) => {
105	    const delta = w.comparable && w.current !== null && w.previous !== null
106	      ? `${w.current - w.previous >= 0 ? '+' : ''}${w.current - w.previous}s`
107	      : '—';
108	    const verdict = w.regressed ? '**regressed**' : w.comparable ? 'steady' : `too few runs (${w.runs} / ${w.priorRuns})`;
109	    return `| \`${w.name}\` | ${fmt(w.current)} | ${fmt(w.previous)} | ${delta} | ${verdict} |`;
110	  });
111	  const stepLines = steps.length
112	    ? ['', 'Slowest steps of the most recent run of the slowest workflow:', '',
113	      ...steps.map((s) => `- ${s.name} — ${s.seconds}s`)]
114	    : [];
115	  return [
116	    `CI duration for \`${repo}\`, median per workflow over the last ${WINDOW_DAYS} days against the ${WINDOW_DAYS} before.`,
117	    `Rewritten by the \`ci-performance\` task on each run — last ${nowIso}.`,
118	    '',
119	    '| Workflow | This window | Previous | Delta | |',
120	    '|---|---|---|---|---|',
121	    ...(rows.length ? rows : ['| _no completed runs in either window_ | — | — | — | — |']),
122	    ...stepLines,
123	    '',
124	    `A workflow is called regressed only when its median is both ≥${REGRESSION_RATIO}x and ≥${REGRESSION_SECONDS}s above the previous window, with at least ${MIN_RUNS_PER_WINDOW} runs in each — otherwise a quiet week or one requeued run reads as a regression.`,
125	    '',
126	    'Method: the `ci-performance-evaluation` skill.',
127	  ].join('\n');
128	}
129	
130	// The standing record this task keeps. Its own, named here and nowhere else.
131	export const TRACKER_TITLE = '[claudinite] CI performance';
132	
