134	  const repo = process.env.GITHUB_REPOSITORY;
135	  if (!repo || !repo.includes('/')) throw new Error('GITHUB_REPOSITORY is not set (owner/repo)');
136	  if (!process.env.GITHUB_TOKEN) throw new Error('GITHUB_TOKEN is not set — the scheduler always provides it');
137	  const gh = makeGh();
