140	  if (status !== 200) throw new Error(`run ledger unreadable: GET actions/runs returned ${status}`);
141	  const runs = json?.workflow_runs ?? [];
142	  const nowMs = Date.now();
143	  const summary = summarize(runs, nowMs);
144	
145	  // The step breakdown of the slowest workflow's latest run — one extra read, and
146	  // the thing any investigation would fetch first anyway.
147	  let steps = [];
148	  const slowest = summary.workflows[0];
149	  if (slowest) {
150	    const latest = runs.find((r) => (r.name || r.path) === slowest.name);
151	    if (latest) {
152	      const jobs = await gh(`/repos/${repo}/actions/runs/${latest.id}/jobs`);
153	      steps = slowestSteps(jobs.json?.jobs?.[0]);
154	    }
155	  }
156	
157	  const nowIso = new Date(nowMs).toISOString();
158	  const body = reportBody(summary, { repo, nowIso, steps });
159	  for (const w of summary.workflows) {
160	    log(`${w.name}: ${fmt(w.current)} (was ${fmt(w.previous)})${w.regressed ? ' — REGRESSED' : ''}`);
161	  }
162	
